import { defineConfig, type Plugin } from 'vite';
import path from 'node:path';
import fs from 'node:fs';

// Serves ../art (outside the spike root) at /art and lists prop PNGs at /art-list,
// so the optional ?sprites=1 mode can load art generated by another agent. Dev/preview only.
const artDir = path.resolve(import.meta.dirname, '../art');

function artPlugin(): Plugin {
  const mw = (req: any, res: any, next: () => void) => {
    const url = decodeURIComponent((req.url || '').split('?')[0]);
    if (url === '/art-list') {
      const dir = path.join(artDir, 'p0-test', 'props');
      const files = fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.toLowerCase().endsWith('.png')) : [];
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify(files));
      return;
    }
    if (url.startsWith('/art/')) {
      const f = path.join(artDir, url.slice(5));
      if (f.startsWith(artDir) && fs.existsSync(f) && fs.statSync(f).isFile()) {
        res.setHeader('Content-Type', 'image/png');
        fs.createReadStream(f).pipe(res);
        return;
      }
    }
    next();
  };
  return {
    name: 'sneakaboo-art',
    configureServer(s) { s.middlewares.use(mw); },
    configurePreviewServer(s) { s.middlewares.use(mw); },
  };
}

export default defineConfig({
  plugins: [artPlugin()],
  server: { host: true, port: 5173, strictPort: false },
  preview: { host: true, port: 4173 },
  build: { target: 'es2022', chunkSizeWarningLimit: 700 },
});
